#!/usr/bin/env python3
"""Regenerate the immutable runtime SPIR-V bundle with the pinned toolchain."""

from __future__ import annotations

import argparse
import hashlib
import json
import shutil
import struct
import subprocess
import tempfile
from pathlib import Path


BUNDLE_ROOT = Path(__file__).resolve().parent
DENSE_ROOT = BUNDLE_ROOT.parent
FROZEN_MANIFEST = BUNDLE_ROOT / "frozen_manifest.json"
BUILD_GATE = DENSE_ROOT / "build" / "build_gate.py"
SPIRV_MAGIC = 0x07230203


def sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def sha256_file(path: Path) -> str:
    return sha256_bytes(path.read_bytes())


def run(command: list[str], label: str) -> subprocess.CompletedProcess[str]:
    result = subprocess.run(command, text=True, capture_output=True, check=False)
    if result.returncode != 0:
        details = "\n".join(part for part in (result.stdout, result.stderr) if part)
        raise RuntimeError(f"{label} failed ({result.returncode})\n{details}")
    return result


def verify_tool(identity: dict[str, object]) -> str:
    name = str(identity["name"])
    discovered = shutil.which(name)
    if discovered is None:
        raise RuntimeError(f"required pinned tool unavailable: {name}")
    resolved = Path(discovered).resolve()
    expected_path = Path(str(identity["resolved_path"]))
    if resolved != expected_path:
        raise RuntimeError(f"{name} resolved to {resolved}, expected {expected_path}")
    actual_executable_sha = sha256_file(resolved)
    if actual_executable_sha != identity["executable_sha256"]:
        raise RuntimeError(f"{name} executable identity changed")
    version = run([str(resolved), "--version"], f"identify {name}").stdout
    if sha256_bytes(version.encode("utf-8")) != identity["version_output_sha256"]:
        raise RuntimeError(f"{name} version output identity changed")
    if not version.startswith(str(identity["version"])):
        raise RuntimeError(f"{name} version label changed")
    return str(resolved)


def render_words(binaries: list[bytes]) -> str:
    lines = ["// Generated by regenerate_frozen_bundle.py; do not edit.", ""]
    for index, data in enumerate(binaries):
        if len(data) % 4 != 0:
            raise RuntimeError(f"shader {index} byte count is not word-aligned")
        words = struct.unpack(f"<{len(data) // 4}I", data)
        lines.append(
            f"alignas(4) constexpr std::array<std::uint32_t, {len(words)}> "
            f"kShaderWords{index} = {{{{"
        )
        for cursor in range(0, len(words), 8):
            chunk = ", ".join(f"0x{word:08x}U" for word in words[cursor:cursor + 8])
            lines.append(f"    {chunk},")
        lines.extend(["}};", ""])
    return "\n".join(lines)


def regenerate(output: Path) -> None:
    manifest = json.loads(FROZEN_MANIFEST.read_text(encoding="utf-8"))
    if manifest.get("schema_version") != 1:
        raise RuntimeError("unsupported frozen shader manifest schema")
    shaders = manifest.get("shaders")
    if not isinstance(shaders, list) or len(shaders) != 11:
        raise RuntimeError("frozen shader manifest must contain exactly eleven shaders")
    compiler = verify_tool(manifest["compiler"])
    validator = verify_tool(manifest["validator"])
    if output.exists() and any(output.iterdir()):
        raise RuntimeError("output directory must be empty")
    output.mkdir(parents=True, exist_ok=True)

    with tempfile.TemporaryDirectory(prefix="pw-build-gate-") as temporary:
        gate_output = Path(temporary) / "gate"
        run(
            ["python3", str(BUILD_GATE), "--output", str(gate_output)],
            "official dense build gate",
        )
        gate_manifest = json.loads(
            (gate_output / "manifest.json").read_text(encoding="utf-8")
        )
        if gate_manifest["target_environment"] != manifest["target_environment"]:
            raise RuntimeError("build gate target environment changed")
        if Path(gate_manifest["toolchain"]["glslangValidator"]).resolve() != Path(compiler):
            raise RuntimeError("build gate used a different compiler")
        if Path(gate_manifest["toolchain"]["spirv-val"]).resolve() != Path(validator):
            raise RuntimeError("build gate used a different validator")
        gate_by_source = {
            shader["source_path"]: shader for shader in gate_manifest["shaders"]
        }
        seen_kinds: set[str] = set()
        seen_assets: set[str] = set()
        binaries: list[bytes] = []
        for index, expected in enumerate(shaders):
            kind = str(expected["kind"])
            asset_path = str(expected["asset_path"])
            if kind in seen_kinds or asset_path in seen_assets:
                raise RuntimeError("duplicate shader kind or asset path")
            seen_kinds.add(kind)
            seen_assets.add(asset_path)
            source_path = str(expected["source_path"])
            source = DENSE_ROOT / source_path
            if sha256_file(source) != expected["source_sha256"]:
                raise RuntimeError(f"source identity changed: {source_path}")
            actual = gate_by_source.get(source_path)
            if actual is None or actual["spirv_path"] is None:
                raise RuntimeError(f"build gate did not compile canonical shader: {source_path}")
            for key in ("source_sha256", "spirv_sha256"):
                if actual[key] != expected[key]:
                    raise RuntimeError(f"{key} changed for {source_path}")
            binary_path = gate_output / actual["spirv_path"]
            data = binary_path.read_bytes()
            if len(data) // 4 != expected["word_count"]:
                raise RuntimeError(f"word count changed for {source_path}")
            if len(data) < 20 or struct.unpack_from("<I", data)[0] != SPIRV_MAGIC:
                raise RuntimeError(f"invalid SPIR-V header for {source_path}")
            run(
                [validator, "--target-env", "vulkan1.1", str(binary_path)],
                f"validate {source_path}",
            )
            destination = output / asset_path
            destination.parent.mkdir(parents=True, exist_ok=True)
            destination.write_bytes(data)
            binaries.append(data)

        (output / "shader_bundle_data.inc").write_text(
            render_words(binaries), encoding="utf-8"
        )


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--output", required=True, type=Path)
    args = parser.parse_args()
    try:
        regenerate(args.output.resolve())
    except (OSError, RuntimeError, ValueError, KeyError, json.JSONDecodeError) as error:
        print(f"frozen shader regeneration failed: {error}")
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
